}

function fr_seed_ysq_templates(): void
{
    $forms = ['ysq-long', 'ysq-short'];
    $texts = fr_ysq_template_texts();
    $titles = DB::all("SELECT test_id, code, title_fa FROM " . DB::t('test_scales') .
                      " WHERE test_id IN (SELECT id FROM " . DB::t('tests') . " WHERE engine='ysq')");
    $nameOf = [];
    foreach ($titles as $t) { $nameOf[$t['test_id'] . '|' . $t['code']] = $t['title_fa']; }

    foreach ($forms as $slug) {
        $tid = (int)(DB::val("SELECT id FROM " . DB::t('tests') . " WHERE slug=?", [$slug]) ?: 0);
        if (!$tid) continue;
        $exists = (int)DB::val("SELECT COUNT(*) FROM " . DB::t('analysis_templates') . " WHERE test_id=?", [$tid]);
        if ($exists >= 36) continue;
        foreach ($texts as $code => [$freeBody, $fullBody]) {
            $fa = $nameOf[$tid . '|' . $code] ?? $code;
            fr_ins_tpl($tid, $code, 'any', 'free', 'طرحوارهٔ «' . $fa . '» در یک نگاه',
                       '<p>' . $freeBody . '</p>');
            fr_ins_tpl($tid, $code, 'high', 'full', 'تحلیل عمیق طرحوارهٔ «' . $fa . '»', $fullBody);
            fr_ins_tpl($tid, $code, 'very_high', 'full', 'تحلیل عمیق طرحوارهٔ «' . $fa . '» (فعال و پررنگ)', $fullBody);
        }
        // تحلیل کلی نسخهٔ ویژه
        if (!(int)DB::val("SELECT COUNT(*) FROM " . DB::t('analysis_templates') . " WHERE test_id=? AND scale_code IS NULL AND level='full'", [$tid])) {
            fr_ins_tpl($tid, null, 'overall', 'full', 'جمع‌بندی تخصصی نقشهٔ طرحواره‌ها',
                '<p>طرحواره‌های فوق، «نقشه‌ی راهِ احساسی» صورت گرفته شما را تشکیل می‌دهند: الگوهایی که در کودکی برای بقا ساخته شدند و امروز نیاز به بازنگری دارند. هر طرحوارهٔ فعال، هم یک گلوگاه و هم یک پیام است؛ پیامِ اینکه کدام نیاز کودکی هنوز شنیده نشده است.</p><p>پیشنهاد درمانی: با یک روان‌درمانگر آشنا به طرحواره‌درمانی (Schema Therapy) کار کنید تا این الگوها در امنیت رابطهٔ درمانی بازنویسی شوند. این گزارش شروعِ راه است، نه پایان آن. 🦢</p>');
        }
    }
}
